@'
import assert from 'node:assert/strict';
function outcome(n,g,u,q){
  if(!Number.isInteger(n)||n<=0||!Number.isInteger(g)||!Number.isInteger(u)||g<0||u<0||g+u>n||!Number.isFinite(q)||q<0||q>1)throw new RangeError('invalid cohort');
  const lower=g/n, upper=(g+u)/n;
  return {lower,upper,status:lower>=q?'pass':upper<q?'fail':'unresolved'};
}
const direct=[
  {n:10000,g:9800,u:200,q:0.99,expected:'unresolved'},
  {n:10000,g:9800,u:200,q:0.98,expected:'pass'},
  {n:10000,g:9700,u:100,q:0.99,expected:'fail'},
  {n:10000,g:9900,u:100,q:0.99,expected:'pass'},
  {n:10000,g:9800,u:0,q:0.99,expected:'fail'},
  {n:10000,g:0,u:10000,q:0.99,expected:'unresolved'}
];
const directResults=direct.map(c=>{const actual=outcome(c.n,c.g,c.u,c.q);assert.equal(actual.status,c.expected);return {...c,...actual};});
const invalid=[{n:0,g:0,u:0,q:0.99},{n:10,g:-1,u:1,q:0.99},{n:10,g:5,u:-1,q:0.99},{n:10,g:8,u:3,q:0.99}];
for(const c of invalid)assert.throws(()=>outcome(c.n,c.g,c.u,c.q),RangeError);
let combinations=0;
const thresholds=[{num:0,den:1},{num:1,den:2},{num:99,den:100},{num:1,den:1}];
for(let n=1;n<=40;n++)for(let g=0;g<=n;g++)for(let u=0;u<=n-g;u++)for(const q of thresholds){
  let anyPass=false,anyFail=false;
  for(let goodUnknown=0;goodUnknown<=u;goodUnknown++){
    if((g+goodUnknown)*q.den>=q.num*n)anyPass=true;else anyFail=true;
  }
  const expected=!anyFail?'pass':!anyPass?'fail':'unresolved';
  assert.equal(outcome(n,g,u,q.num/q.den).status,expected,JSON.stringify({n,g,u,q}));
  combinations++;
}
assert.equal(combinations,49360);
console.log(JSON.stringify({classification:'retrospective arithmetic rerun; not an agent behavioral evaluation',directResults,invalidControls:invalid,invalidControlsRejected:invalid.length,enumeration:{n:'1..40',g:'0..n',u:'0..n-g',thresholds,combinations,oracle:'Enumerate every possible count of good outcomes among the unresolved operations, using integer threshold cross-products.'}},null,2));
