import { readFileSync,readdirSync,statSync,existsSync } from 'node:fs';
import { resolve,dirname } from 'node:path';
const files=[];function walk(d){for(const n of readdirSync(d)){const p=resolve(d,n);if(statSync(p).isDirectory())walk(p);else if(p.endsWith('.md'))files.push(p);}}walk(resolve('skills/capacity-planning'));
const links=[];for(const file of files)for(const m of readFileSync(file,'utf8').matchAll(/\[[^\]]+\]\(([^)]+)\)/g)){const target=m[1];if(/^[a-z]+:/i.test(target))continue;const [p,anchor]=target.split('#');const abs=resolve(dirname(file),p);let valid=existsSync(abs);if(valid&&anchor){const heads=[...readFileSync(abs,'utf8').matchAll(/^#{1,6}\s+(.+)$/gm)].map(x=>x[1].toLowerCase().replace(/[^\w\s-]/g,'').replace(/\s+/g,'-'));valid=heads.includes(anchor);}links.push({file,target,valid});}
console.log(JSON.stringify({markdownFiles:files.length,links,invalid:links.filter(x=>!x.valid).length},null,2));if(links.some(x=>!x.valid))process.exitCode=1;
